insert into fp_card (id, sort, cat, orig, name, is_dg, trio_owner, descr, conception, planning, execution, status, holder, parked_note, img) values
('H1', 1, 'home', 'Childcare Helpers', 'Kinder|betreuung & Hilfen', true, null, 'Babysitter, Nanny oder Haushaltshilfe finden, einweisen und koordinieren.', '', '', '', 'parked', null, '', null),
('H2', 2, 'home', 'Cleaning', 'Putzen', false, null, 'Unser Zuhause ist so sauber, dass wir uns wohlfühlen.', 'Sieht, wo es schmutzig wird, und hat im Blick, wann Bad, Küche und Böden dran sind.', 'Legt fest, was wann geputzt wird, und sorgt für Putzmittel und Geräte.', 'Putzt oder sorgt dafür, dass geputzt wird – regelmäßig, nicht erst, wenn es auffällt.', 'deck', null, '', 'H2.png'),
('H3', 3, 'home', 'Dishes', 'Geschirr', true, null, 'Nach dem Essen ist die Küche wieder benutzbar.', 'Merkt, wann der Geschirrspüler voll oder fertig ist und was per Hand gespült werden muss.', 'Bestimmt, wann ein- und ausgeräumt wird, und hält Tabs und Spülmittel vorrätig.', 'Räumt ein, startet, räumt aus und spült, was nicht in die Maschine darf.', 'deck', null, '', 'H3.png'),
('H4', 4, 'home', 'Dry Cleaning', 'Textil|reinigung', false, null, 'Was in die Reinigung oder zur Schneiderei muss, kommt hin und wieder zurück.', 'Merkt, was gereinigt, geändert oder repariert werden muss.', 'Weiß, welche Reinigung oder Schneiderei, und plant, wann hin- und abgeholt wird.', 'Bringt die Sachen hin, holt sie ab und räumt sie wieder ein.', 'deck', null, '', 'H4.png'),
('H5', 5, 'home', 'Garbage', 'Müll', true, null, 'Der Müll ist getrennt, und die Tonnen stehen rechtzeitig draußen.', 'Merkt, wann Eimer voll sind und welche Tonne als Nächstes abgeholt wird.', 'Kennt Abfuhrkalender und Trennsystem und besorgt Müllsäcke.', 'Leert die Eimer, trennt, bringt die Tonnen raus und wieder rein.', 'deck', null, '', 'H5.png'),
('H6', 6, 'home', 'Groceries', 'Lebensmittel|einkauf', true, null, 'Zu Hause ist immer da, was wir zum Essen und Kochen brauchen.', 'Merkt, was zur Neige geht und was für Mahlzeiten, Jausen und Anlässe fehlt.', 'Führt die Einkaufsliste und entscheidet, wo und wann eingekauft wird: Supermarkt, Markt oder Lieferung.', 'Kauft ein, räumt alles weg und kümmert sich um Pfand und Taschen.', 'deck', null, '', 'H6.png'),
('H7', 7, 'home', 'Home Furnishings', 'Einrichtung', false, null, 'Möbel und Einrichtung aussuchen, kaufen und aufstellen.', '', '', '', 'parked', null, '', null),
('H8', 8, 'home', 'Home Goods & Supplies', 'Haushalts|bedarf', true, null, 'Klopapier, Waschmittel, Glühbirnen & Co. gehen nie aus.', 'Hat im Blick, welche Haushaltsdinge zur Neige gehen.', 'Führt die Liste und entscheidet, wo nachgekauft wird: Drogerie, Baumarkt oder online.', 'Kauft nach und räumt die Vorräte ein.', 'deck', null, '', 'H8.png'),
('H9', 9, 'home', 'Home Maintenance', 'Instand|haltung', true, null, 'Was kaputtgeht, wird repariert, und was gewartet werden muss, wird gewartet.', 'Bemerkt Defekte und weiß, wann Wartungen fällig sind: Heizung, Filter, Rauchmelder.', 'Entscheidet, ob selbst repariert oder ein Handwerker kommt, holt Angebote ein und macht Termine.', 'Repariert selbst oder ist da, wenn der Handwerker kommt, und prüft das Ergebnis.', 'deck', null, '', 'H9.png'),
('H10', 10, 'home', 'Home Purchase/Rental, Mortgage & Insurance', 'Wohnen: Kauf, Miete, Kredit & Ver|sicherung', false, null, 'Alles rund um Vertrag, Finanzierung und Versicherung unseres Zuhauses.', 'Hat Fristen, Zinsbindung, Nebenkosten und Versicherungsschutz im Blick.', 'Vergleicht, verhandelt und bereitet Entscheidungen vor – auch für das Haus in Augsburg.', 'Unterschreibt, zahlt, kündigt und legt die Unterlagen ab.', 'deck', null, '', 'H10.png'),
('H11', 11, 'home', 'Hosting', 'Gäste einladen', false, null, 'Besuch einladen, bewirten und beherbergen.', '', '', '', 'parked', null, '', null),
('H12', 12, 'home', 'Laundry', 'Wäsche', true, null, 'Alle haben saubere, trockene Kleidung im Schrank.', 'Merkt, wann der Wäschekorb voll ist und was bis wann gebraucht wird, etwa das Trikot.', 'Sortiert nach Farben und Programmen und plant Wasch- und Trockenzeiten.', 'Wäscht, hängt auf oder trocknet, legt zusammen und räumt ein.', 'deck', null, '', 'H12.png'),
('H13', 13, 'home', 'Lawn & Plants', 'Garten & Pflanzen', false, null, 'Pflanzen drinnen und draußen bleiben am Leben.', 'Sieht, was gegossen, geschnitten oder umgetopft werden muss, und denkt an die Jahreszeit.', 'Plant Pflege und Einkäufe und klärt, wer im Urlaub gießt.', 'Gießt, mäht, schneidet und pflanzt.', 'deck', null, '', 'H13.png'),
('H14', 14, 'home', 'Mail', 'Post', true, null, 'Briefkasten leeren, Post sortieren und bearbeiten.', '', '', '', 'parked', null, '', null),
('H15', 15, 'home', 'Meals (Weekday Breakfast)', 'Frühstück unter der Woche', true, null, 'An Schultagen gibt es morgens ein Frühstück.', 'Weiß, was morgens gebraucht wird und was fehlt.', 'Plant, was es gibt, damit es in den Morgenablauf passt.', 'Macht das Frühstück und räumt danach ab.', 'deck', null, '', 'H15.png'),
('H16', 16, 'home', 'Meals (School Lunch)', 'Schul|jause', true, null, 'Leander hat jeden Schultag eine Jause und eine Trinkflasche dabei.', 'Weiß, was Leander mag und was in der Box war und wieder zurückkam.', 'Plant die Jausen für die Woche und sorgt für die Zutaten.', 'Richtet die Jausenbox her, füllt die Flasche und spült beides abends.', 'deck', null, '', 'H16.png'),
('H17', 17, 'home', 'Meals (Weekday Dinner)', 'Abendessen unter der Woche', true, null, 'An Werktagen steht ein Abendessen auf dem Tisch.', 'Denkt rechtzeitig daran, was es heute und diese Woche gibt.', 'Plant die Mahlzeiten passend zu Terminen und Vorräten.', 'Kocht oder sorgt dafür, dass gekocht wird, und deckt den Tisch.', 'deck', null, '', 'H17.png'),
('H18', 18, 'home', 'Meals (Weekend)', 'Essen am Wochenende', false, null, 'Am Wochenende ist fürs Essen gesorgt – gekocht, auswärts oder bestellt.', 'Denkt an die Mahlzeiten am Wochenende, auch bei Ausflügen und Besuch.', 'Plant, was gekocht wird oder wohin es geht.', 'Kocht, reserviert oder bestellt.', 'deck', null, '', 'H18.png'),
('H19', 19, 'home', 'Memories & Photos', 'Erinnerungen & Fotos', false, null, 'Fotos sortieren, Alben gestalten, Erinnerungen aufbewahren.', '', '', '', 'parked', null, '', null),
('H20', 20, 'home', 'Money Manager', 'Finanzen', false, null, 'Wir wissen, wo unser Geld steht und wofür wir es ausgeben.', 'Hat Konten, Budget, Sparziele und Steuern im Blick.', 'Plant Budget und Rücklagen und bereitet die Steuererklärung vor.', 'Überweist, spart, legt ab und reicht die Steuer ein.', 'deck', null, '', 'H20.png'),
('H21', 21, 'home', 'Storage, Garage & Seasonal Items', 'Keller, Garage & Saisonales', false, null, 'Keller und Garage ordnen, Saisonales ein- und ausräumen.', '', '', '', 'parked', null, '', null),
('H22', 22, 'home', 'Tidying Up, Organizing & Donations', 'Auf|räumen, Ordnen & Aus|sortieren', true, null, 'Alles hat seinen Platz, und was wir nicht mehr brauchen, geht weiter.', 'Sieht Chaos-Ecken und Dinge, die zu klein sind oder nicht mehr benutzt werden.', 'Entscheidet, wo was hinkommt und was verschenkt, verkauft oder entsorgt wird.', 'Räumt auf, sortiert aus und bringt Spenden weg.', 'deck', null, '', 'H22.png'),
('O1', 23, 'out', 'Auto', 'Auto', false, null, 'Das Auto fährt, ist versichert und sicher.', 'Denkt an Service, Pickerl bzw. TÜV, Reifenwechsel und Tankstand.', 'Macht Werkstatttermine und vergleicht Versicherungen.', 'Bringt das Auto hin, wechselt Reifen, tankt und wäscht es.', 'deck', null, '', 'O1.png'),
('O2', 24, 'out', 'Birthday Celebrations (Other Kids)', 'Kinder|geburtstage anderer Kinder', false, null, 'Einladungen beantworten, Geschenke besorgen, hinbringen und abholen.', '', '', '', 'parked', null, '', null),
('O3', 25, 'out', 'Calendar Keeper', 'Familien|kalender', true, null, 'Alle Termine der Familie stehen an einem Ort, und alle wissen, was ansteht.', 'Bemerkt neue Termine aus Schule, Arbeit, Vereinen und Familie.', 'Trägt ein, erkennt Überschneidungen und klärt, wer wann wo ist.', 'Erinnert rechtzeitig und hält den Kalender aktuell.', 'deck', null, '', 'O3.png'),
('O4', 26, 'out', 'Cash & Bills', 'Bargeld & Rech|nungen', true, null, 'Rechnungen sind bezahlt, und es ist genug Bargeld da.', 'Merkt, wann Rechnungen kommen und wann Bargeld oder Taschengeld gebraucht wird.', 'Richtet Daueraufträge ein und behält Fälligkeiten im Blick.', 'Zahlt, hebt ab und legt Belege ab.', 'deck', null, '', 'O4.png'),
('O5', 27, 'out', 'Charity, Community Service & Good Deeds (Adults)', 'Ehrenamt & Spenden', false, null, 'Sich engagieren und entscheiden, wofür wir spenden.', '', '', '', 'parked', null, '', null),
('O6', 28, 'out', 'Civic Engagement & Cultural Enrichment', 'Gesellschaft & Kultur', false, null, 'Wählen gehen, Kultur erleben, informiert bleiben.', '', '', '', 'parked', null, '', null),
('O7', 29, 'out', 'Electronics & IT', 'Elektronik & IT', false, null, 'Geräte, WLAN, Konten und Updates funktionieren.', 'Merkt, wenn etwas hakt, und denkt an Updates, Backups und Passwörter.', 'Wählt Geräte und Verträge aus und plant Einrichtung oder Austausch.', 'Richtet ein, repariert, aktualisiert und hilft bei Problemen.', 'deck', null, '', 'O7.png'),
('O8', 30, 'out', 'Extracurricular (Non-Sports)', 'Freizeit|kurse (ohne Sport)', true, null, 'Leander besucht Kurse jenseits des Sports – Musik, Kreatives, Hobbys.', 'Merkt, was Leander interessiert, und denkt an Anmeldefristen.', 'Sucht Kurse aus, meldet an und plant Zeiten und Material.', 'Bringt hin oder sorgt fürs Hinkommen, zahlt Beiträge und hält Kontakt zur Kursleitung.', 'deck', null, '', 'O8.png'),
('O9', 31, 'out', 'Extracurricular (Sports)', 'Sport & Vereine', true, null, 'Leander kann regelmäßig Sport machen.', 'Denkt an Training, Turniere, Ausrüstung und Mitgliedsbeiträge.', 'Sucht Verein oder Kurs aus, meldet an und koordiniert Termine.', 'Bringt hin, holt ab, wäscht das Trikot und ist bei Wettkämpfen dabei.', 'deck', null, '', 'O9.png'),
('O10', 32, 'out', 'First Aid, Safety & Emergency', 'Erste Hilfe, Sicher|heit & Notfall', false, null, 'Wir sind auf Notfälle vorbereitet.', 'Denkt an Hausapotheke, Rauchmelder, Notfallnummern und Erste-Hilfe-Kurse.', 'Prüft Ablaufdaten, plant Kurse und legt Notfallpläne fest.', 'Füllt auf, tauscht Batterien und hängt die Nummern sichtbar auf.', 'deck', null, '', 'O10.png'),
('O11', 33, 'out', 'Packing & Unpacking (Local)', 'Packen im Alltag', true, null, 'Alle haben dabei, was sie für den Tag brauchen.', 'Denkt an Turnsachen, Schwimmzeug, Hausschuhe und Regenjacke.', 'Legt fest, was wann eingepackt wird, und macht Checklisten.', 'Packt ein, kontrolliert und packt abends wieder aus.', 'deck', null, '', 'O11.png'),
('O12', 34, 'out', 'Packing & Unpacking (Travel)', 'Packen für Reisen', false, null, 'Für Urlaube und Reisen packen und wieder auspacken.', '', '', '', 'parked', null, 'Momentan nicht relevant', null),
('O13', 35, 'out', 'Points, Miles & Coupons', 'Bonuspunkte & Gutscheine', false, null, 'Bonusprogramme und Gutscheine nutzen, bevor sie verfallen.', '', '', '', 'parked', null, '', null),
('O14', 36, 'out', 'Returns & Store Credits', 'Rück|sendungen & Gutschriften', false, null, 'Rücksendungen erledigen und Gutschriften einlösen.', '', '', '', 'parked', null, '', null),
('O15', 37, 'out', 'School Breaks (Non-Summer)', 'Schulferien (ohne Sommer)', false, null, 'Herbst-, Weihnachts-, Semester- und Osterferien sind geplant.', 'Hat die Ferientermine und Betreuungslücken im Blick.', 'Plant Betreuung, Ausflüge, Besuche bei den Großeltern oder Kurse.', 'Bucht, meldet an und sorgt für den Ablauf.', 'deck', null, '', 'O15.png'),
('O16', 38, 'out', 'School Breaks (Summer)', 'Sommer|ferien', false, null, 'Die Sommerferien planen: Betreuung, Camps, Urlaub.', '', '', '', 'parked', null, 'Momentan nicht relevant', null),
('O17', 39, 'out', 'School Forms', 'Schul|formulare', false, null, 'Zettel, Einverständniserklärungen und Anmeldungen aus der Schule sind erledigt.', 'Schaut Mitteilungsheft, Schul-App und Postfach durch.', 'Weiß, was bis wann zurück muss und was dafür nötig ist.', 'Füllt aus, unterschreibt, zahlt und gibt rechtzeitig ab.', 'deck', null, '', 'O17.png'),
('O18', 40, 'out', 'Social Plans (Couples)', 'Treffen mit anderen Paaren', false, null, 'Gemeinsame Unternehmungen mit befreundeten Paaren planen.', '', '', '', 'parked', null, '', null),
('O19', 41, 'out', 'Transportation (Kids)', 'Fahrdienste (Kind)', true, null, 'Leander zu Schule, Training und Terminen bringen und abholen.', '', '', '', 'parked', null, '', null),
('O20', 42, 'out', 'Travel', 'Reisen', false, null, 'Urlaube und Reisen planen und buchen.', '', '', '', 'parked', null, 'Momentan nicht relevant', null),
('O21', 43, 'out', 'Tutoring & Coaching', 'Fördern & Fordern', false, null, 'Leander bekommt, was er gerade braucht: Unterstützung, wo es hakt, und Herausforderung, wo er mehr will.', 'Merkt, wo Leander unter- oder überfordert ist, und hat Fristen für Kurse, Wettbewerbe, Begabtenwerkstätten oder Nachhilfe im Blick.', 'Sucht passende Angebote aus, meldet an, stimmt sich bei Bedarf mit der Schule ab und plant die Termine.', 'Bringt hin, zahlt, hält Kontakt zu Lehrkräften und Kursleitung und fragt Leander, was ihm gefällt und was nicht.', 'deck', null, '', 'O21.png'),
('O22', 44, 'out', 'Weekend Plans (Family)', 'Wochen|end|planung (Familie)', false, null, 'Unsere Wochenenden haben einen Plan – oder bewusst keinen.', 'Denkt rechtzeitig an das kommende Wochenende, an Wetter und Wünsche.', 'Schlägt Ausflüge vor, stimmt ab und reserviert.', 'Packt, bucht Tickets und sorgt dafür, dass es losgeht.', 'deck', null, '', 'O22.png'),
('C1', 45, 'care', 'Bathing & Grooming (Kids)', 'Körper|pflege (Kind)', true, null, 'Leander ist sauber und gepflegt.', 'Hat Duschen, Haarewaschen, Nägel und Friseur im Blick.', 'Legt Routinen fest und sorgt für Shampoo, Zahnpasta und Co.', 'Erinnert, hilft und begleitet, bis Leander es selbst schafft.', 'deck', null, '', 'C1.png'),
('C2', 46, 'care', 'Beauty & Wardrobe (Her)', 'Pflege & Kleidung (Katja)', false, null, 'Katja hat, was sie zum Wohlfühlen und Anziehen braucht.', 'Merkt, was fehlt oder ersetzt werden muss.', 'Plant Einkäufe und Friseurtermine.', 'Kauft ein und geht zu den Terminen.', 'deck', null, '', 'C2.png'),
('C3', 47, 'care', 'Bedtime Routine', 'Abend|routine', true, null, 'Leander kommt entspannt und rechtzeitig ins Bett.', 'Hat die Uhrzeit im Blick und weiß, was abends noch ansteht.', 'Kennt den Ablauf – Essen, Zähne, Lesen, Licht aus – und passt ihn an Tage mit Terminen an.', 'Begleitet den Abend nach dem vereinbarten Ablauf bis Licht aus.', 'deck', null, '', 'C3.png'),
('C4', 48, 'care', 'Birth Control', 'Verhütung', false, null, 'Verhütung gemeinsam verantworten.', '', '', '', 'parked', null, '', null),
('C5', 49, 'care', 'Clothes & Accessories (Kids)', 'Kinder|kleidung', false, null, 'Leander hat passende Kleidung für jede Jahreszeit und jeden Anlass.', 'Merkt, was zu klein, kaputt oder für die nächste Saison nötig ist.', 'Kennt Größen und Bezugsquellen und entscheidet: neu, gebraucht oder geerbt.', 'Kauft, lässt anprobieren, sortiert aus und gibt weiter.', 'deck', null, '', 'C5.png'),
('C6', 50, 'care', 'Dental (Kids)', 'Zahnarzt (Kind)', false, null, 'Leanders Zähne sind gesund und regelmäßig kontrolliert.', 'Denkt an Kontrolltermine, Prophylaxe und Zahnspange.', 'Macht Termine und klärt die Kosten.', 'Geht mit hin und kümmert sich um die Nachsorge.', 'deck', null, '', null),
('C7', 51, 'care', 'Diapering & Potty Training', 'Wickeln & Sauber|werden', true, null, 'Windeln und Töpfchentraining.', '', '', '', 'parked', null, '', null),
('C8', 52, 'care', 'Estate Planning & Life Insurance', 'Vor|sorge & Lebens|versicherung', false, null, 'Für den Fall der Fälle ist vorgesorgt.', 'Denkt an Testament, Vollmachten, Sorgerechtsverfügung und Versicherungen.', 'Holt Beratung ein, vergleicht und bereitet Entscheidungen vor.', 'Unterschreibt, hinterlegt und hält die Unterlagen aktuell.', 'deck', null, '', null),
('C9', 53, 'care', 'Friendships & Social Media (Kids)', 'Freund|schaften & Social Media (Kind)', true, null, 'Leander hat gute Freundschaften und einen gesunden Umgang mit Chats und Medien.', 'Hat im Blick, mit wem Leander Zeit verbringt und was online passiert.', 'Organisiert Treffen und spricht Regeln für Handy und Chats ab.', 'Bringt zu Verabredungen, lädt Freunde ein und schaut bei Chats hin.', 'deck', null, '', null),
('C10', 54, 'care', 'Grooming & Wardrobe (Him)', 'Pflege & Kleidung (Matthias)', false, null, 'Matthias hat, was er zum Wohlfühlen und Anziehen braucht.', 'Merkt, was fehlt oder ersetzt werden muss.', 'Plant Einkäufe und Friseurtermine.', 'Kauft ein und geht zu den Terminen.', 'deck', null, '', null),
('C11', 55, 'care', 'Health Insurance', 'Kranken|versicherung', false, null, 'Krankenversicherung abschließen, prüfen und Leistungen abrechnen.', '', '', '', 'parked', null, '', null),
('C12', 56, 'care', 'Homework, Projects & School Supplies', 'Haus|übung, Projekte & Schul|sachen', true, null, 'Die HÜ ist gemacht, und die Schulsachen sind vollständig.', 'Weiß, welche HÜ, Tests und Projekte anstehen und welches Material fehlt.', 'Plant Lernzeiten und Reihenfolge und besorgt Schulsachen.', 'Begleitet die HÜ, kontrolliert, unterschreibt und packt fertig.', 'deck', null, '', null),
('C13', 57, 'care', 'Medical & Healthy Living', 'Gesundheit & Arzt|termine', true, null, 'Arzttermine, Impfungen und gesunde Lebensweise.', '', '', '', 'parked', null, 'Abgedeckt über Besondere Bedürfnisse & psychische Gesundheit und Zahnarzt', null),
('C14', 58, 'care', 'Morning Routine', 'Morgen|routine', true, null, 'Alle kommen morgens rechtzeitig und vollständig aus dem Haus.', 'Hat die Zeit im Blick und weiß, was heute dabei sein muss.', 'Kennt den Ablauf – Aufstehen, Anziehen, Frühstück, Zähne, Losgehen – und passt ihn an.', 'Weckt, begleitet und sorgt dafür, dass es pünktlich losgeht.', 'deck', null, '', null),
('C15', 59, 'care', 'Parents & In-Laws', 'Eltern & Schwieger|eltern', false, null, 'Kontakt halten und unterstützen, wo die Großeltern Hilfe brauchen.', '', '', '', 'parked', null, '', null),
('C16', 60, 'care', 'Pets', 'Haustiere', true, null, 'Sissi und Franz sind versorgt und gesund.', 'Denkt an Futter, Katzenklo, Impfungen und Tierarzt.', 'Hält den Futtervorrat, macht Tierarzttermine und organisiert die Urlaubsbetreuung.', 'Füttert, putzt das Klo und bringt die Katzen zum Tierarzt.', 'deck', null, '', null),
('C17', 61, 'care', 'School Service', 'Mithilfe in der Schule', false, null, 'Elternverein, Ausflüge begleiten, Schulfeste unterstützen.', '', '', '', 'parked', null, '', null),
('C18', 62, 'care', 'School Transitions', 'Schul|wechsel', false, null, 'Leanders Wechsel aufs Gymnasium gelingt gut.', 'Denkt an Anmeldung, Probeunterricht, Schulweg und Eingewöhnung.', 'Vergleicht Schulen, hält Fristen ein und bereitet Leander vor.', 'Meldet an, begleitet die ersten Tage und hält Kontakt zur neuen Schule.', 'deck', null, '', null),
('C19', 63, 'care', 'Self-Care (Her)', 'Self-Care (Katja)', false, '00000000-0000-4000-8000-00000000000a', 'Katja hat Zeit für das, was sie gesund und kräftig hält.', 'Merkt, was sie braucht: Sport, Schlaf, Arzttermine, Pausen.', 'Blockt feste Zeiten dafür im Kalender.', 'Nimmt sich die Zeit – und hält sie.', 'deck', '00000000-0000-4000-8000-00000000000a', '', null),
('C20', 64, 'care', 'Self-Care (Him)', 'Self-Care (Matthias)', false, '00000000-0000-4000-8000-00000000000b', 'Matthias hat Zeit für das, was ihn gesund und kräftig hält.', 'Merkt, was er braucht: Sport, Schlaf, Arzttermine, Pausen.', 'Blockt feste Zeiten dafür im Kalender.', 'Nimmt sich die Zeit – und hält sie.', 'deck', '00000000-0000-4000-8000-00000000000b', '', null),
('C21', 65, 'care', 'Special Needs & Mental Health (Kids)', 'Besondere Bedürf|nisse & psychische Gesund|heit (Kind)', true, null, 'Leander bekommt die Begleitung, die er braucht – Ärzte, Therapie, Rezepte und Struktur im Alltag.', 'Hat Termine, Medikation, Rezepte und Gespräche mit Schule und Therapie im Blick, auch allgemeine Arzttermine.', 'Sucht Fachleute, koordiniert Termine und Kosten und plant die Unterstützung.', 'Geht zu Terminen, holt Rezepte und Medikamente und setzt Absprachen im Alltag um.', 'deck', null, '', null),
('C22', 66, 'care', 'Teacher Communication', 'Kommunikation mit Lehr|kräften', false, null, 'Wir sind mit Leanders Lehrkräften in gutem Kontakt.', 'Liest Nachrichten und merkt, wann ein Gespräch nötig ist.', 'Vereinbart Sprechstunden und bereitet Gespräche vor.', 'Führt Gespräche, antwortet und gibt Infos an den anderen weiter.', 'deck', null, '', null),
('M1', 67, 'magic', 'Adult Friendships (Her)', 'Freund|schaften (Katja)', false, '00000000-0000-4000-8000-00000000000a', 'Katja pflegt ihre Freundschaften.', 'Merkt, wen sie lange nicht gesehen hat.', 'Verabredet sich und plant Treffen.', 'Trifft sich, ruft an, ist da.', 'deck', '00000000-0000-4000-8000-00000000000a', '', null),
('M2', 68, 'magic', 'Adult Friendships (Him)', 'Freund|schaften (Matthias)', false, '00000000-0000-4000-8000-00000000000b', 'Matthias pflegt seine Freundschaften.', 'Merkt, wen er lange nicht gesehen hat.', 'Verabredet sich und plant Treffen.', 'Trifft sich, ruft an, ist da.', 'deck', '00000000-0000-4000-8000-00000000000b', '', null),
('M3', 69, 'magic', 'Birthday Celebrations (Your Kids)', 'Leanders Geburts|tag', false, null, 'Leanders Geburtstag wird so gefeiert, wie er es sich wünscht.', 'Denkt rechtzeitig an Wünsche, Gäste und Feier.', 'Plant Feier, Einladungen, Geschenke und Kuchen.', 'Lädt ein, backt, dekoriert, feiert und räumt auf.', 'deck', null, '', null),
('M4', 70, 'magic', 'Discipline & Screen Time', 'Regeln & Bild|schirm|zeit', true, null, 'Wir haben klare, gemeinsame Regeln – auch für die Bildschirmzeit.', 'Merkt, wo Regeln fehlen, unklar sind oder nicht mehr passen.', 'Legt die Regeln gemeinsam fest und hält fest, was streng gilt und was locker.', 'Setzt die Regeln konsequent um, auch wenn es unbequem ist.', 'deck', null, '', null),
('M5', 71, 'magic', 'Extended Family', 'Verwandtschaft', false, null, 'Kontakt zur erweiterten Familie pflegen.', '', '', '', 'parked', null, '', null),
('M6', 72, 'magic', 'Fun! & Playing', 'Spielen & Spaß', false, null, 'Wir spielen und lachen zusammen.', 'Merkt, wann es Zeit für Spaß ist und worauf Leander Lust hat.', 'Plant Spieleabende, Ausflüge und Überraschungen.', 'Spielt mit – mit vollem Einsatz.', 'deck', null, '', null),
